param([string]$Root=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..\..')).Path)
$p=Join-Path $Root 'packages/contracts/openapi/v1.openapi.json';$s=Get-Content $p -Raw|ConvertFrom-Json
foreach($pathProp in $s.paths.psobject.Properties){foreach($methodProp in $pathProp.Value.psobject.Properties){$op=$methodProp.Value;$name="$($op.operationId)Response";$outcome=if($op.operationId -match 'Booking|Seat|Taxi|Trip'){'bookingOrTripReference'}elseif($op.operationId -match 'Wallet|Withdrawal|Payment'){'financialOperationReference'}elseif($op.operationId -match 'Complaint|Evidence|Compliance'){'caseOrEvidenceReference'}else{'operationReference'};$schema=[pscustomobject]@{allOf=@(@{'$ref'='#/components/schemas/CommandResponse'},@{type='object';additionalProperties=$false;required=@($outcome);properties=@{$outcome=@{type='string';minLength=1}}})};$s.components.schemas|Add-Member NoteProperty $name $schema -Force;$op.responses.'200'.content.'application/json'.schema=@{'$ref'="#/components/schemas/$name"}}}
[IO.File]::WriteAllText($p,($s|ConvertTo-Json -Depth 80),(New-Object Text.UTF8Encoding($false)))
